"use client";

import Matter from "matter-js";
import Image from "next/image";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import { usePhysics } from "./PhysicsContext";

interface DesktopIconProps {
  height?: number;
  iconSrc: string;
  label: string;
  onDoubleClick?: () => void;
  width?: number;
  x: number;
  y: number;
}

const DesktopIcon: React.FC<DesktopIconProps> = ({
  x,
  y,
  label,
  iconSrc,
  width = 64,
  height = 64,
  onDoubleClick,
}) => {
  const { engine, isReady } = usePhysics();
  const bodyRef = useRef<Matter.Body | null>(null);
  const elementRef = useRef<HTMLDivElement>(null);
  const [isSelected, setIsSelected] = useState(false);

  // Initialize Physics Body
  useEffect(() => {
    if (!(engine && isReady && elementRef.current)) {
      return;
    }

    // Create a rectangular body for the icon
    // High air friction to stop it from drifting endlessly (like "bumper cars" in fluid)
    const body = Matter.Bodies.rectangle(x, y, width + 20, height + 20, {
      frictionAir: 0.15, // Damping - stops relatively quickly after being hit
      restitution: 0.5, // Bounciness
      density: 0.001,
      label: `icon-${label}`,
    });

    bodyRef.current = body;
    Matter.World.add(engine.world, body);

    // Sync loop
    const updatePosition = () => {
      if (bodyRef.current && elementRef.current) {
        const { position, angle } = bodyRef.current;
        // Icons usually don't rotate in OS X, so we might lock rotation or keep it subtle
        // For "bumper cars", subtle rotation is fun.
        const degrees = angle * (180 / Math.PI);
        elementRef.current.style.transform = `translate(${position.x - (width + 40) / 2}px, ${position.y - (height + 20) / 2}px) rotate(${degrees}deg)`;
      }
    };

    Matter.Events.on(engine, "afterUpdate", updatePosition);

    return () => {
      if (engine && bodyRef.current) {
        Matter.World.remove(engine.world, bodyRef.current);
        Matter.Events.off(engine, "afterUpdate", updatePosition);
      }
    };
  }, [engine, isReady, height, label, width, x, y]); // Only run once on mount to set initial position

  return (
    <div
      className="group pointer-events-auto absolute top-0 left-0 flex select-none flex-col items-center justify-start"
      onClick={(e) => e.stopPropagation()}
      onDoubleClick={(e) => {
        e.stopPropagation();
        onDoubleClick?.();
      }}
      onMouseDown={() => {
        // Do NOT stop propagation. We want the event to bubble to the GravityDesktop container
        // so that Matter.MouseConstraint can detect the mouse down and initiate a physics drag.
        setIsSelected(true);
      }}
      ref={elementRef}
      style={{
        width: width + 40, // Click area
        willChange: "transform",
        // Position handled by transform
      }}
    >
      <div
        className={`relative mb-1 ${isSelected ? "brightness-[0.8]" : ""} pointer-events-none`}
        style={{ width, height }}
      >
        <Image
          alt={label}
          className="object-contain drop-shadow-md"
          draggable={false}
          height={height}
          src={iconSrc}
          width={width}
        />
      </div>

      {/* Label */}
      <div
        className={`wrap-break-word pointer-events-none max-w-full rounded-full px-2 py-[2px] text-center font-medium text-[12px] leading-tight ${
          isSelected
            ? "bg-[#3333cc] text-white"
            : "text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]"
        }
                `}
        style={{ fontFamily: '"Lucida Grande", sans-serif' }}
      >
        {label}
      </div>
    </div>
  );
};

export default DesktopIcon;

"use client";

import Matter from "matter-js";
import type React from "react";
import { createContext, useContext, useEffect, useRef, useState } from "react";

interface PhysicsContextType {
  engine: Matter.Engine | null;
  isReady: boolean;
  world: Matter.World | null;
}

const PhysicsContext = createContext<PhysicsContextType>({
  engine: null,
  world: null,
  isReady: false,
});

export const usePhysics = () => useContext(PhysicsContext);

interface PhysicsProviderProps {
  children: React.ReactNode;
  debug?: boolean; // If true, renders the matter.js debug canvas
}

export const PhysicsProvider: React.FC<PhysicsProviderProps> = ({
  children,
  debug = false,
}) => {
  const [engine] = useState(() => {
    const newEngine = Matter.Engine.create();
    newEngine.enableSleeping = false;
    newEngine.gravity.y = 0;
    return newEngine;
  });
  const [isReady, setIsReady] = useState(false);
  const sceneRef = useRef<HTMLDivElement>(null);
  const engineRef = useRef<Matter.Engine | null>(null);
  const renderRef = useRef<Matter.Render | null>(null);
  const runnerRef = useRef<Matter.Runner | null>(null);

  useEffect(() => {
    engineRef.current = engine;
    setIsReady(true);

    // Optional: Debug Renderer
    if (debug && sceneRef.current && engine) {
      const render = Matter.Render.create({
        element: sceneRef.current,
        engine,
        options: {
          width: window.innerWidth,
          height: window.innerHeight,
          wireframes: true, // Set to false for solid colors if needed
          background: "transparent",
        },
      });
      renderRef.current = render;
      Matter.Render.run(render);
    }

    // Create Runner
    if (engine) {
      const runner = Matter.Runner.create();
      runnerRef.current = runner;
      Matter.Runner.run(runner, engine);
    }

    return () => {
      // Cleanup
      if (renderRef.current) {
        Matter.Render.stop(renderRef.current);
        if (renderRef.current.canvas) {
          renderRef.current.canvas.remove();
        }
      }
      if (runnerRef.current) {
        Matter.Runner.stop(runnerRef.current);
      }
      if (engine) {
        Matter.World.clear(engine.world, false);
        Matter.Engine.clear(engine);
      }
    };
  }, [debug, engine]);

  return (
    <PhysicsContext.Provider
      value={{ engine, world: engine?.world || null, isReady }}
    >
      {debug && (
        <div
          className="pointer-events-none absolute inset-0 z-50 opacity-50"
          ref={sceneRef}
        />
      )}
      {children}
    </PhysicsContext.Provider>
  );
};

"use client";

import Matter from "matter-js";
import type React from "react";
import { useEffect, useRef } from "react";
import { usePhysics } from "./PhysicsContext";

interface DesktopWindowProps {
  children?: React.ReactNode;
  height?: number;
  onClose?: () => void;
  title: string;
  width?: number;
  x: number;
  y: number;
}

const DesktopWindow: React.FC<DesktopWindowProps> = ({
  x,
  y,
  width = 400,
  height = 300,
  title,
  children,
  onClose,
}) => {
  const { engine, isReady } = usePhysics();
  const bodyRef = useRef<Matter.Body | null>(null);
  const elementRef = useRef<HTMLDivElement>(null);

  // Keep track of internal close request to remove from physics properly
  const handleClose = (e: React.MouseEvent) => {
    e.stopPropagation();
    onClose?.();
  };

  useEffect(() => {
    if (!(engine && isReady && elementRef.current)) {
      return;
    }

    // Create the window body
    const body = Matter.Bodies.rectangle(x, y, width, height, {
      friction: 0.1,
      restitution: 0.4, // Bouncy windows
      density: 0.005, // Heavier than icons
      chamfer: { radius: 10 }, // Rounded corners collision
      collisionFilter: {
        category: 0x00_02, // Category: Window
        // Mask: Default (Walls/Icons=1) | DockBase(4) | DockIcons(8)
        // Excludes: Other Windows (2)
        mask: 0x00_01 | 0x00_04 | 0x00_08,
      },
    });

    bodyRef.current = body;
    Matter.World.add(engine.world, body);

    // Sync loop
    const updatePosition = () => {
      if (bodyRef.current && elementRef.current) {
        const { position, angle } = bodyRef.current;
        const degrees = angle * (180 / Math.PI);

        elementRef.current.style.transform = `translate(${position.x - width / 2}px, ${position.y - height / 2}px) rotate(${degrees}deg)`;
      }
    };

    Matter.Events.on(engine, "afterUpdate", updatePosition);

    return () => {
      if (engine && bodyRef.current) {
        Matter.World.remove(engine.world, bodyRef.current);
        Matter.Events.off(engine, "afterUpdate", updatePosition);
      }
    };
  }, [engine, height, isReady, width, x, y]); // Run once on mount

  return (
    <div
      className="pointer-events-auto absolute top-0 left-0 flex select-none flex-col overflow-hidden rounded-lg border border-gray-400/50 bg-[#e8e8e8] shadow-2xl"
      ref={elementRef}
      style={{
        width,
        height,
        willChange: "transform",
        boxShadow: "0 20px 50px rgba(0,0,0,0.5)",
      }}
    >
      {/* Window Bar */}
      <div className="flex h-6 w-full cursor-grab items-center border-[#b4b4b4] border-b bg-linear-to-b from-[#f6f6f6] to-[#dcdcdc] px-2 active:cursor-grabbing">
        <div className="flex space-x-2">
          <button
            className="h-3 w-3 rounded-full border border-[#e0443e] bg-[#ff5f57] shadow-inner transition-colors hover:bg-[#ff5f57]/80 active:bg-[#bf4c46]"
            onClick={handleClose}
          />
          <div className="h-3 w-3 rounded-full border border-[#dea123] bg-[#ffbd2e] shadow-inner" />
          <div className="h-3 w-3 rounded-full border border-[#1aab29] bg-[#28ca41] shadow-inner" />
        </div>
        <div className="pointer-events-none flex-1 text-center font-semibold text-gray-600 text-xs drop-shadow-xs">
          {title}
        </div>
        <div className="w-14" /> {/* Spacer for centering */}
      </div>

      {/* Content Area */}
      <div
        className="pointer-events-auto relative flex-1 overflow-hidden bg-white"
        onMouseDown={(e) => e.stopPropagation()}
      >
        {/* Brushed metal sidebar imitation or just content */}
        {children || (
          <div className="p-4 font-sans text-gray-800 text-sm">
            <h3 className="mb-2 font-bold">Welcome to Aqua</h3>
            <p>
              This window is a rigid body. You can throw it against the walls.
            </p>
            <div className="mt-4 rounded border border-blue-200 bg-blue-100 p-2">
              Status:{" "}
              <span className="font-bold text-green-600">Physics Active</span>
            </div>
          </div>
        )}

        {/* Stripe overlay for retro feel */}
        <div className="pointer-events-none absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/diagonal-stripes-light.png')] opacity-[0.03]" />
      </div>
    </div>
  );
};

export default DesktopWindow;

import Matter from "matter-js";
import type React from "react";
import { useEffect, useRef } from "react";
import { usePhysics } from "./PhysicsContext";

interface GravityDesktopProps {
  children: React.ReactNode;
}

const GravityDesktop: React.FC<GravityDesktopProps> = ({ children }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { engine, isReady } = usePhysics();

  // Setup World Boundaries & Mouse Interaction
  useEffect(() => {
    if (!(engine && isReady && containerRef.current)) {
      return;
    }

    const world = engine.world;
    const width = window.innerWidth;
    const height = window.innerHeight;
    const wallThickness = 100;

    // 1. Create Boundaries (Walls)
    // Only floor is strictly "needed" for gravity, but walls keep things in view
    const walls = [
      // Floor
      Matter.Bodies.rectangle(
        width / 2,
        height + wallThickness / 2 - 20,
        width,
        wallThickness,
        { isStatic: true, label: "Wall" }
      ),
      // Ceiling
      Matter.Bodies.rectangle(
        width / 2,
        -wallThickness * 2,
        width,
        wallThickness,
        { isStatic: true, label: "Wall" }
      ),
      // Left Wall
      Matter.Bodies.rectangle(
        -wallThickness / 2,
        height / 2,
        wallThickness,
        height,
        { isStatic: true, label: "Wall" }
      ),
      // Right Wall
      Matter.Bodies.rectangle(
        width + wallThickness / 2,
        height / 2,
        wallThickness,
        height,
        { isStatic: true, label: "Wall" }
      ),
    ];

    Matter.World.add(world, walls);

    // 2. Mouse Constraint for Dragging
    const mouse = Matter.Mouse.create(containerRef.current);
    const mouseConstraint = Matter.MouseConstraint.create(engine, {
      mouse,
      constraint: {
        stiffness: 0.2,
        render: {
          visible: false,
        },
      },
      // Explicitly allow mouse to grab all categories
      collisionFilter: {
        category: 0x00_01,
        mask: 0xff_ff_ff_ff,
      },
    });

    // Prevent mouse from capturing scroll events (if we had scroll)
    // mouse.element.removeEventListener("mousewheel", mouse.mousewheel);
    // mouse.element.removeEventListener("DOMMouseScroll", mouse.mousewheel);

    Matter.World.add(world, mouseConstraint);

    // 3. Handle Resize
    let lastWidth = window.innerWidth;
    let lastHeight = window.innerHeight;

    const handleResize = () => {
      const newWidth = window.innerWidth;
      const newHeight = window.innerHeight;

      // Calculate resize speed/direction
      const deltaX = newWidth - lastWidth;
      const deltaY = newHeight - lastHeight;

      // Update wall positions
      Matter.Body.setPosition(walls[0], {
        x: newWidth / 2,
        y: newHeight + wallThickness / 2 - 20,
      }); // Floor
      Matter.Body.setPosition(walls[1], {
        x: newWidth / 2,
        y: -wallThickness * 2,
      }); // Ceiling
      Matter.Body.setPosition(walls[2], {
        x: -wallThickness / 2,
        y: newHeight / 2,
      }); // Left
      Matter.Body.setPosition(walls[3], {
        x: newWidth + wallThickness / 2,
        y: newHeight / 2,
      }); // Right

      // Apply "Bumper Car" Fling Effect
      const bodies = Matter.Composite.allBodies(world);

      if (deltaX < 0) {
        // Right wall crashing in
        bodies.forEach((body) => {
          if (body.isStatic) {
            return;
          }
          const distToRight = newWidth - body.position.x;
          if (distToRight < 150) {
            const impactForce = Math.min(Math.abs(deltaX) * 0.2, 10);
            Matter.Body.setVelocity(body, {
              x: body.velocity.x - impactForce,
              y: body.velocity.y + (Math.random() - 0.5) * 5,
            });
            Matter.Body.setAngularVelocity(
              body,
              body.angularVelocity + (Math.random() - 0.5) * 0.2
            );
          }
        });
      }

      if (deltaY < 0) {
        // Floor crashing up
        bodies.forEach((body) => {
          if (body.isStatic) {
            return;
          }
          const distToBottom = newHeight - body.position.y;
          if (distToBottom < 150) {
            const impactForce = Math.min(Math.abs(deltaY) * 0.2, 10);
            Matter.Body.setVelocity(body, {
              x: body.velocity.x + (Math.random() - 0.5) * 5,
              y: body.velocity.y - impactForce, // Fling up
            });
            Matter.Body.setAngularVelocity(
              body,
              body.angularVelocity + (Math.random() - 0.5) * 0.2
            );
          }
        });
      }

      lastWidth = newWidth;
      lastHeight = newHeight;
    };

    // 4. Safety Bounds Check (Prevent Tunneling)
    const checkBounds = () => {
      const bodies = Matter.Composite.allBodies(engine.world);
      const w = window.innerWidth;
      const h = window.innerHeight;
      const padding = 20; // Allow slight off-screen before clamping

      bodies.forEach((body) => {
        if (body.isStatic) {
          return; // Ignore walls
        }

        let { x, y } = body.position;
        let { x: vx, y: vy } = body.velocity;
        let clamped = false;

        // Clamp X
        if (x < -padding) {
          x = padding;
          vx = Math.abs(vx) * 0.5; // Bounce back right with damping
          clamped = true;
        } else if (x > w + padding) {
          x = w - padding;
          vx = -Math.abs(vx) * 0.5; // Bounce back left
          clamped = true;
        }

        // Clamp Y
        if (y < -padding * 2) {
          // Allow more space up top (off-screen fling valid sometimes, but let's clamp for safety)
          y = padding;
          vy = Math.abs(vy) * 0.5;
          clamped = true;
        } else if (y > h + padding) {
          y = h - padding;
          vy = -Math.abs(vy) * 0.5;
          clamped = true;
        }

        if (clamped) {
          Matter.Body.setPosition(body, { x, y });
          Matter.Body.setVelocity(body, { x: vx, y: vy });
        }
      });
    };

    Matter.Events.on(engine, "beforeUpdate", checkBounds);

    window.addEventListener("resize", handleResize);

    return () => {
      Matter.World.remove(world, walls);
      Matter.World.remove(world, mouseConstraint);
      window.removeEventListener("resize", handleResize);
    };
  }, [engine, isReady]);

  return (
    <div
      className="relative mt-[22px] h-[calc(100vh-22px)] w-full overflow-hidden bg-blue-900"
      ref={containerRef}
    >
      {/* Wallpaper - Blue Swirl */}
      <div className="pointer-events-none absolute inset-0 z-0">
        <div
          className="absolute inset-0 bg-[url('https://www.razisyed.cv/experiments/gravity-physics-ui-layout/wallpaper.png')] bg-center bg-cover"
          style={{ backgroundSize: "100% 100%" }} // Force stretch to match OS X behavior often
        />
      </div>

      {/* Icons and Windows Container */}
      <div className="pointer-events-none relative z-10 h-full w-full">
        {/* 
                    IMPORTANT: The physics container must be interactive, but we put pointer-events-none on the wrapper
                    so clicks pass through to the canvas if needed, BUT standard React events on children need pointer-events-auto.
                    However, for Matter.js MouseConstraint to work, the containerRef element needs to receive events.
                    If children block events, Matter might not "see" the mouse.
                    Actually, Matter listens on the element provided.
                    Children like DOM Overlay elements (Windows) map specific DOM interaction to physics bodies.
                    But to drag a "body" via Matter mouse constraint, the mouse event must originate or propagate to the container.
                 */}
        {/* React children need to re-enable pointer events if they want standard onClick, 
                    BUT for full physics dragging of "Window" (which mimics the body), 
                    the Window component itself is a DIV that matches the Body position.
                    If we drag that DIV, we aren't using Matter MouseConstraint directly.

                    Wait, `DesktopWindow` is just a visual representation synced to a body.
                    To drag it with Matter.js physical mouse constraint, the user must be clicking on the "canvas" area corresponding to the body.
                    BUT we are rendering HTML elements ON TOP of the physics world.
                    So the mouse hits the HTML element, NOT the containerRef directly where Matter listens.

                    This means standard MouseConstraint won't work if the HTML element blocks the mouse.
                    OR we need to manually pass drag events to Matter.

                    ALTERNATIVE:
                    DesktopWindow uses a custom drag handler that applies force to the body?
                    OR we set `pointer-events-none` on the DesktopWindow so clicks go through to the background?
                    But then we can't click buttons inside the window (close, minimize).

                    Hybrid approach:
                    DesktopWindow has a "Handle" (Title bar). Pushing on it applies MouseConstraint? No.

                    Let's stick to the simplest fix requested: "im also not able to drag those windows".
                    If `DesktopWindow` is a rigid body, the `MouseConstraint` needs to "grab" it.
                    If the `div` is on top, `Matter` doesn't see the mouse down.

                    Fix: We can make the Title Bar `pointer-events-none` (so click goes through to underlying canvas/body area?)
                    NO, `Matter` doesn't know about the `div` shape.

                    Actually, we can use `react-draggable` or keep it simple:
                    If `Matter` is running, we can let `Matter` handle dragging IF we forward events?

                    Easiest "Physics Drag" with DOM overlay:
                    The DOM overlay tracks the Body.
                    To drag, we need to apply force to the body.
                    The standard `MouseConstraint` is great but requires the mouse to be on the canvas.

                    If we want "Window" to be draggable via the TitleBar:
                    We can attach a `mousedown` on the TitleBar that instantiates a constraint or applies velocity.

                    HOWEVER, looking at the previous implementation's intent:
                    It seems it expected MouseConstraint to work.

                    For now, I will re-enable MouseConstraint on the container.
                    AND I will ensure the DesktopWindow allows events to pass through on non-interactive parts?
                    Or, better, I will assume the previous dev (my past self) knew that MouseConstraint works if the element is part of the DOM that Matter is attached to?
                    Matter attaches to `containerRef`.
                    If `Mouse.create(containerRef.current)` is used, it adds listeners to that DIV.
                    Events bubble up. If `DesktopWindow` stops propagation, Matter won't see it.
                    `DesktopWindow` handles Close with `e.stopPropagation()`.
                    The Title Bar has `cursor-grab`.

                    If user clicks Title Bar, event bubbles to `GravityDesktop` div. Matter receives it.
                    Matter checks if a body is under the mouse.
                    The Body is at (x,y). The DOM element is at (x,y).
                    Visually they align.
                    So Matter SHOULD find the body and drag it.

                    So just restoring this file should work.
                 */}
        {children}
      </div>
    </div>
  );
};

export default GravityDesktop;

